/// drop-zone: A file list that accepts drops
private struct DropZoneExample0: View {
    /// A dropped file, copied before the system removes its temporary file.
    struct DroppedFile: Transferable {
        let url: URL

        static var transferRepresentation: some TransferRepresentation {
            FileRepresentation(importedContentType: .item) { received in
                let copy = FileManager.default.temporaryDirectory.appendingPathComponent(received.file.lastPathComponent)
                try? FileManager.default.removeItem(at: copy)
                try FileManager.default.copyItem(at: received.file, to: copy)
                return DroppedFile(url: copy)
            }
        }
    }

    @Environment(\.monarchTheme) private var theme
    @State private var items = [
        MonarchFileListItem(id: "seed-1", name: "team-charter.pdf", size: 420_000),
    ]
    @State private var refused: [MonarchFileUploadRejection] = []
    @State private var isTargeted = false

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space3) {
            MonarchFileUpload(
                allowedContentTypes: [.image, .pdf],
                maxSize: 10_485_760,
                hint: "Images or PDF, up to 10 MB. Or drop files on the list.",
                variant: .compact,
                labels: MonarchFileUploadLabels(browse: "Upload files")
            ) { accepted, _ in
                items += accepted.map { MonarchFileListItem(id: $0.url.absoluteString, name: $0.name, size: $0.size) }
            }
            if !refused.isEmpty {
                MonarchInlineNotice(refused.map(\.message).joined(separator: "\n"), tone: .danger)
            }
            MonarchFileList(items, label: "Shared files")
                .padding(theme.spacing.space2)
                .background(
                    RoundedRectangle(cornerRadius: theme.radius.md)
                        .fill(isTargeted ? theme.colors.accentSubtle : Color.clear)
                )
                .dropDestination(
                    for: DroppedFile.self,
                    action: { dropped, _ in
                        let result = MonarchFileUpload.validate(
                            dropped.map { MonarchFileUploadFile(url: $0.url) },
                            allowedContentTypes: [.image, .pdf],
                            maxSize: 10_485_760,
                            currentCount: items.count
                        )
                        items += result.accepted.map { MonarchFileListItem(id: $0.url.absoluteString, name: $0.name, size: $0.size) }
                        refused = result.rejected
                        return !result.accepted.isEmpty
                    },
                    isTargeted: { isTargeted = $0 }
                )
        }
    }
}

/// editor-toolbar: Every control
private struct EditorToolbarExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var active: Set<MonarchEditorTool> = [.heading(2)]

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space2) {
            MonarchEditorToolbar(
                groups: [
                    [.undo, .redo],
                    [.paragraph, .heading(1), .heading(2), .heading(3)],
                    [.bold, .italic, .strikethrough, .code, .link],
                    [.bulletList, .orderedList],
                    [.blockquote, .codeBlock],
                ],
                active: active,
                disabled: [.redo],
                onLink: { url in
                    if url == nil { active.remove(.link) } else { active.insert(.link) }
                },
                action: { tool in
                    if active.contains(tool) { active.remove(tool) } else { active.insert(tool) }
                }
            )
            Text("Meeting notes").monarchTextStyle(.heading)
            Text("Agree the ") + Text("release date").bold() + Text(" and who owns the help article.")
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text("\u{2022} " + "Draft the announcement")
                Text("\u{2022} " + "Review the checklist")
            }
        }
        .padding(theme.spacing.space2)
        .overlay(
            RoundedRectangle(cornerRadius: theme.radius.md)
                .strokeBorder(theme.colors.borderDefault)
        )
    }
}

