    @State private var cover: URL?

    var body: some View {
        MonarchMediaUpload("Cover image", url: $cover, helper: "Shown at the top of the page.", maxImageSize: 10_485_760, videoUnavailable: "Videos can’t be added to this item.", labels: MonarchMediaUploadLabels(addImage: "Drop an image here", imageHint: { _ in "PNG, JPG, GIF or WebP up to 10 MB" })) { file, context in
            context.reportProgress(1)
            return MonarchMediaUploadResult(url: file.url)
        }
    }
}

