/// page-tree: Navigation
private struct PageTreeExample0: View {
    @State private var page: String? = "setup"
    private let groups = [
        MonarchPageTreeGroup(id: "start", label: "Getting started", pages: [MonarchPageTreePage(id: "welcome", title: "Welcome"), MonarchPageTreePage(id: "setup", title: "Set up your account")]),
        MonarchPageTreeGroup(id: "guides", label: "Guides", pages: [MonarchPageTreePage(id: "invite", title: "Invite your team"), MonarchPageTreePage(id: "import", title: "Import data"), MonarchPageTreePage(id: "reports", title: "Build a report")]),
        MonarchPageTreeGroup(id: "reference", label: "Reference", pages: [MonarchPageTreePage(id: "glossary", title: "Glossary")]),
    ]

    var body: some View {
        VStack(alignment: .center, spacing: 8) {
            MonarchPageTree(groups, selection: $page)
                .frame(height: 540)
            Divider()
            MonarchButton("All documents", variant: .ghost, size: .sm) {}
                .frame(maxWidth: .infinity)
        }
    }
}

/// page-tree: An organiser
private struct PageTreeExample1: View {
    @State private var page: String?
    @State private var groups = [
        MonarchPageTreeGroup(id: "basics", label: "Basics", pages: [
            MonarchPageTreePage(id: "welcome", title: "Welcome"),
            MonarchPageTreePage(id: "setup", title: "Set up"),
        ]),
        MonarchPageTreeGroup(id: "guides", label: "Guides", pages: []),
    ]

    var body: some View {
        MonarchPageTree(
            groups,
            selection: $page,
            onReorder: { newGroups, _ in groups = newGroups },
            onAddGroup: { name in groups.append(MonarchPageTreeGroup(id: name, label: name, pages: [])) },
            onDeletePage: { id in
                for index in groups.indices { groups[index].pages.removeAll { $0.id == id } }
            }
        )
        .frame(minHeight: 320)
    }
}

