/// upload-queue: Mixed statuses
private struct UploadQueueExample0: View {
    @State private var items = [
        MonarchUploadQueueItem(id: "1", name: "quarterly-report.pdf", size: 2_516_582, status: .done),
        MonarchUploadQueueItem(id: "2", name: "site-photo-01.jpg", size: 4_299_162, status: .uploading, progress: 62.0 / 100),
        MonarchUploadQueueItem(id: "3", name: "site-photo-02.jpg", size: 3_984_589, status: .queued),
        MonarchUploadQueueItem(id: "4", name: "floor-plan.dwg", size: 18_874_368, status: .failed, errorMessage: "Upload interrupted. Check your connection and try again."),
        MonarchUploadQueueItem(id: "5", name: "archive.zip", size: 125_829_120, status: .failed, errorMessage: "Larger than the 100 MB limit.", isRetryable: false),
    ]

    var body: some View {
        MonarchUploadQueue(
            items,
            usesBinaryUnits: true,
            onCancel: { id in
                items = items.map { $0.id == id ? MonarchUploadQueueItem(id: $0.id, name: $0.name, size: $0.size, status: .cancelled) : $0 }
            },
            onRetry: { id in
                items = items.map { $0.id == id ? MonarchUploadQueueItem(id: $0.id, name: $0.name, size: $0.size, status: .queued) : $0 }
            },
            onRemove: { id in items.removeAll { $0.id == id } },
            onClearFinished: { items.removeAll { !$0.status.isActive } }
        )
    }
}

/// version-history-panel: Browse, compare, save and restore
private struct VersionHistoryPanelExample0: View {
    @State private var selection: String?

    private let content: [String: [String]] = [
        "v4": ["# Onboarding guide", "Welcome to the team.", "Your first week: meet your buddy, set up your laptop, read the handbook.", "Ask questions in the help channel.", "Book a check-in with your manager on Friday."],
        "v3": ["# Onboarding guide", "Welcome to the team.", "Your first week: meet your buddy and set up your laptop.", "Ask questions in the help channel."],
        "v2": ["# Onboarding guide", "Welcome!", "Your first week: set up your laptop."],
        "v1": ["# Onboarding guide", "Draft."],
    ]
    private let versions = [
        MonarchVersionHistoryPanelVersion(id: "v4", date: Date(timeIntervalSinceNow: -300), authorName: "Robin Park"),
        MonarchVersionHistoryPanelVersion(id: "v3", date: Date(timeIntervalSinceNow: -10_800), authorName: "Alex Chen", note: "Reviewed"),
        MonarchVersionHistoryPanelVersion(id: "v2", date: Date(timeIntervalSinceNow: -93_600), authorName: "Robin Park", isAutomatic: true),
        MonarchVersionHistoryPanelVersion(id: "v1", date: Date(timeIntervalSinceNow: -518_400), authorName: "Jordan Diaz", note: "First draft"),
    ]

    var body: some View {
        MonarchVersionHistoryPanel(
            "History",
            versions: versions,
            selection: $selection,
            currentLines: content["v4"] ?? [],
            selectedLines: selection.flatMap { content[$0] },
            currentID: "v4",
            onSaveVersion: { _ in },
            onRestore: { _ in },
            onClose: { selection = nil }
        )
    }
}

