/// video-thumbnail: With a poster and duration
private struct VideoThumbnailExample0: View {
    private let picture: Image = {
        let width = 960, height = 540
        guard let context = CGContext(
            data: nil, width: width, height: height, bitsPerComponent: 8, bytesPerRow: 0,
            space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { return Image(systemName: "photo") }
        // Core Graphics counts up from the bottom: flip it so the picture is drawn from the top left.
        context.translateBy(x: 0, y: CGFloat(height))
        context.scaleBy(x: 1, y: -1)
        let colors = [
            CGColor(red: 0.26, green: 0.52, blue: 0.74, alpha: 1),
            CGColor(red: 0.18, green: 0.55, blue: 0.36, alpha: 1),
        ]
        if let gradient = CGGradient(colorsSpace: CGColorSpaceCreateDeviceRGB(), colors: colors as CFArray, locations: [0, 1]) {
            context.drawLinearGradient(
                gradient, start: .zero, end: CGPoint(x: width, y: height), options: [])
        }
        context.setFillColor(red: 1, green: 1, blue: 1, alpha: 0.35)
        context.fillEllipse(in: CGRect(x: 690, y: 70, width: 150, height: 150))
        context.setFillColor(red: 1, green: 1, blue: 1, alpha: 0.5)
        context.move(to: CGPoint(x: 0, y: 540))
        context.addLine(to: CGPoint(x: 0, y: 400))
        context.addLine(to: CGPoint(x: 280, y: 200))
        context.addLine(to: CGPoint(x: 520, y: 360))
        context.addLine(to: CGPoint(x: 700, y: 280))
        context.addLine(to: CGPoint(x: 960, y: 430))
        context.addLine(to: CGPoint(x: 960, y: 540))
        context.fillPath()
        guard let picture = context.makeImage() else { return Image(systemName: "photo") }
        return Image(decorative: picture, scale: 1)
    }()

    var body: some View {
        MonarchVideoThumbnail("Product overview", image: picture, duration: 65)
    }
}

